import sys

def reconstruct_original_ring(N, sums):
    original = [0] * N
    original[0] = sums[0] - sums[N-1]
    for i in range(1, N):
        original[i] = sums[i] - sums[i-1]

    return original

if __name__ == "__main__":
    N = int(sys.stdin.readline().strip())
    sums = list(map(int, sys.stdin.read().splitlines()))

    result = reconstruct_original_ring(N, sums)

    for num in result:
        print(num)
